SELECT impression_date_utc, campaign_id_string, campaign_country, COUNT(DISTINCT user_id) AS reach_users, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM dsp_impressions WHERE user_id IS NOT NULL AND impressions > 0 AND campaign_country = CUSTOM_PARAMETER('dsp_campaign_country') GROUP BY impression_date_utc, campaign_id_string, campaign_country
